void generate_download_path(uint32_t download_id, const content_DownloadTargetCallback* callback, const base_FilePath* suggested_path) {
    // Ensure the function is called on the UI thread
    DCHECK(IsUIThread());

    base_FilePath file_name = base_FilePath_Create();
    base_FilePath_Append(&file_name, base_FilePath_GetBaseName(suggested_path));
    base_FilePath_Append(&file_name, ".crdownload");

    download_TargetDisposition disposition = TARGET_DISPOSITION_USE_SUGGESTED_NAME;
    download_DangerType danger_type = DANGER_TYPE_NOT_DANGEROUS;

    content_DownloadTargetCallback_Invoke(callback, &file_name, disposition, danger_type, NULL, NULL, 0);
}

void generate_download_path(uint32_t download_id, const content_DownloadTargetCallback* callback, const base_FilePath* suggested_path) {
  // Ensure that this is called on the UI thread.
  #ifdef DCHECK_IS_ON
  DCHECK_CURRENTLY_ON(BrowserThread::UI);
  #endif

  // Construct the file name with ".crdownload" extension.
  char file_name[PATH_MAX];
  snprintf(file_name, sizeof(file_name), "%s.crdownload", base_FilePath_basename(suggested_path));

  // Compute the full path.
  base_FilePath full_path = base_FilePath_join(base_FilePath_dirname(suggested_path), file_name);

  // Prepare the callback response.
  content_DownloadTargetCallback_Params params;
  params.path = full_path;
  params.disposition = DOWNLOAD_TARGET_DISPOSITION_PROMPT;
  params.danger_type = DOWNLOAD_DANGER_TYPE_NOT_DANGEROUS;
  params.mime_type = "";
  params.original_name = suggested_path;

  callback->Run(&params);
}

void GenerateDownloadPath(uint32_t download_id, const content::DownloadTargetCallback& callback, const base::FilePath& suggested_path) {
  // Ensure this is called on the UI thread
  DCHECK(content::BrowserThread::CurrentlyOn(content::BrowserThread::UI));

  // Get the base name of the suggested path and append ".crdownload"
  base::FilePath file_name = suggested_path.BaseName().ReplaceExtension(kCrdownloadExtension);

  // Build the full path using the suggested path's directory and the new file name
  base::FilePath full_path = suggested_path.DirName().Append(file_name);

  // Call the callback with the generated path
  callback.Run(full_path, DOWNLOAD_DANGER_TYPE_NOT_DANGEROUS, TARGET_DISPOSITION_PROMPT, base::FilePath());
}

void generate_download_path(uint32_t download_id, const content::DownloadTargetCallback& callback, const base::FilePath& suggested_path) {
    // Check that it is called on the UI thread
    #ifdef DCHECK_IS_ON
    DCHECK_CURRENTLY_ON(content::BrowserThread::UI);
    #endif

    base::FilePath file_name = suggested_path.BaseName();
    std::u16string name_str = file_name.value();
    name_str.append(u".crdownload");

    base::FilePath new_path = suggested_path.DirName().Append(name_str);

    callback.Run(
        new_path,
        download_target_callback::TARGET_DISPOSITION_PROMPT,
        download_target_callback::DANGEROUS_FILE,
        download_id,
        base::DoNothing());
}
